#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
"""Observation window of a session from the FISH model itself (replaces the
'centerpoint's last >= 900 ms stall' heuristic of ksched_split, which only
works on Autoware runs whose localization initialised).

  t_data  = session_data_start_ns   first fire of a periodic timer        (mark_phases, EX attrs)
  t_shut  = shutdown_start_ns       first node_fini of a timer-owning node (mark_phases, EX attrs)
  stimulus = publishes of the publisher-thread F's (ptype 'thread': rosbag
             player, driver I/O threads) — the external input of the run
  window  = [max(t_data, stimulus first) + warmup, min(t_shut, stimulus last)]
            (no publisher thread: [t_data + warmup, t_shut])
warmup: FISH_WARMUP_S (default 10 s wall) — start-up transients (TensorRT first
inference, localization initialisation) are inside the data phase but are not
steady-state behaviour."""
import os


def steady_window(cur, sid, scope='__main__', warmup_s=None):
    """cur: psycopg2 cursor (tuple rows). Returns dict(t_ss, t_end, t_data, t_shut, stim0, stim1, warmup_ns, how)."""
    if warmup_s is None:
        warmup_s = float(os.environ.get('FISH_WARMUP_S', '10'))
    cur.execute("SELECT min((attrs->>'session_data_start_ns')::bigint), min((attrs->>'shutdown_start_ns')::bigint) "
                "FROM graph_nodes WHERE session_id=%s AND scope=%s AND type='EX'", (sid, scope))
    row = cur.fetchone()
    t_data, t_shut = (row[0], row[1]) if row else (None, None)
    cur.execute("SELECT (attrs->>'vpid')::int, (attrs->>'thread_tid')::int FROM graph_nodes "
                "WHERE session_id=%s AND scope=%s AND type='F' AND ptype='thread' AND attrs ? 'vpid'", (sid, scope))
    stim0 = stim1 = None
    for vpid, vtid in cur.fetchall():
        cur.execute("SELECT min(ts_ns), max(ts_ns) FROM ros2_trace WHERE session_id=%s AND vpid=%s AND vtid=%s "
                    "AND event IN ('ros2:rcl_publish','ros2:fish_rcl_publish')", (sid, vpid, vtid))
        a, b = cur.fetchone()
        if a is not None:
            stim0 = a if stim0 is None else min(stim0, a)
            stim1 = b if stim1 is None else max(stim1, b)
    cur.execute("SELECT min(t0_ns), max(t1_ns) FROM gantt_spans WHERE session_id=%s AND scope=%s", (sid, scope))
    s0, s1 = cur.fetchone()
    lo = max(x for x in (t_data, stim0, s0) if x is not None) if any(x is not None for x in (t_data, stim0, s0)) else 0
    hi = min(x for x in (t_shut, stim1, s1) if x is not None) if any(x is not None for x in (t_shut, stim1, s1)) else 0
    w = int(warmup_s * 1e9)
    how = ('stimulus' if stim0 is not None else 'phases' if t_data is not None else 'spans')
    if lo + w >= hi:      # window shorter than the warm-up: keep it, without warm-up
        w = 0; how += ',no-warmup'
    return dict(t_ss=lo + w, t_end=hi, t_data=t_data, t_shut=t_shut, stim0=stim0, stim1=stim1, warmup_ns=w, how=how)
